import React from 'react';

export default function TeacherDashboard({ teacherData }) {
  const myClasses = [
    { class: 'Grade 10 Maths', students: 45, nextLesson: 'Algebra' },
    { class: 'Grade 11 Science', students: 30, nextLesson: 'Physics' },
  ];

  return (
    <div style={{ padding: '40px', backgroundColor: '#f8fafc' }}>
      <h2 style={{ color: '#15803d', marginBottom: '30px' }}>Teacher Portal - {teacherData.name} 👩‍🏫</h2>
      
      <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(300px, 1fr))', gap: '20px' }}>
        {myClasses.map((cls, index) => (
          <div key={index} style={{ background: '#fff', padding: '25px', borderRadius: '15px', borderLeft: '5px solid #15803d', boxShadow: '0 4px 6px rgba(0,0,0,0.05)' }}>
            <h3 style={{ marginBottom: '10px' }}>{cls.class}</h3>
            <p>Students Enrolled: {cls.students}</p>
            <p>Next Topic: <strong>{cls.nextLesson}</strong></p>
            <button style={{ marginTop: '15px', padding: '10px 20px', borderRadius: '8px', border: 'none', background: '#15803d', color: '#fff', cursor: 'pointer' }}>
              Edit Content
            </button>
          </div>
        ))}
      </div>
    </div>
  );
}
